  width: 100%;
  min-width: 0;
  font-size: 12px;
}
.gd-comment-compose input:disabled {
  opacity: 0.6;
}
.gd-board-area {
  grid-area: board;
  width: 100%;
  max-width: min(600px, max(240px, calc(100dvh - 384px)));
  min-width: 0;
  margin: 0 auto;
}
.gd-board-wrap {
  position: relative;
  margin: 0 auto;
}
.gd-wood {
  width: 100%;
  aspect-ratio: 1;
  position: relative;
  border-radius: 11px;
  border: 5px solid #927044;
  background-color: var(--gd-wood);
  background-image:
    repeating-linear-gradient(
      1deg,
      transparent 0,
      transparent 8px,
      var(--gd-grain) 9px,
      transparent 11px
    ),
    linear-gradient(120deg, #fff1bf30, transparent 45%, #68422112);
  box-shadow:
    0 12px 26px #00000025,
    inset 0 0 0 2px #f7dfa25c,
    inset 0 0 30px #a273361c;
}
.gd-grid {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}
.gd-grid line {
  stroke: var(--gd-grid);
  stroke-width: 0.9;
  vector-effect: non-scaling-stroke;
}
.gd-grid circle {
  fill: #715132;
}
.gd-letters {
  position: absolute;
  left: 8%;
  right: 8%;
  bottom: 1.7%;
  display: flex;
  justify-content: space-between;
  color: #755433;
  font-size: 11px;
}
.gd-numbers {
  position: absolute;
  top: 8%;
  bottom: 8%;
  left: 1.5%;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  color: #755433;
  font-size: 11px;
}
.gd-letters span {
  width: 0;
  display: flex;
  justify-content: center;
}
.gd-numbers span {
  height: 0;
  display: flex;
  align-items: center;
}
.gd-spot {
  position: absolute;
  transform: translate(-50%, 50%);
  width: 6%;
  height: 6%;
  border: 0;
  padding: 0;
  background: transparent;
  border-radius: 50%;
}
.gd-spot:disabled {
  opacity: 1;
}
.gd-spot:not(:disabled):hover::before {
  content: "";
  position: absolute;
  inset: 10%;
  border: 1px solid #67553480;
  border-radius: 50%;
  background: #674b2820;
}
.gd-stone {
  display: block;
  position: absolute;
  inset: 7%;
  border-radius: 50%;
  box-shadow: 1px 3px 4px #00000040;
}
.gd-black {
  background: radial-gradient(
    circle at 30% 24%,
    #646967,
    #262b29 43%,
    #0b100e 88%
  );
}
.gd-white {
  background: radial-gradient(circle at 30% 24%, #ffffff, #f1f1e8 55%, #c5ccc4);
  border: 1px solid #aeb5a890;
}
.gd-stone.is-last::after {
  content: "";
  position: absolute;
  width: 16%;
  height: 16%;
  left: 42%;
  top: 42%;
  border-radius: 50%;
  background: #c86849;
}
.gd-stone.is-win {
  outline: 2px solid #e0b76a;
  outline-offset: 1px;
}
.gd-board-footer {
  height: 50px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.gd-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  background: #1d271aa8;
  border-radius: 6px;
  color: #fffbe7;
  pointer-events: none;
}
.gd-overlay strong {
  font-size: 70px;
  font-weight: 500;
  line-height: 1;
}
.gd-overlay button {
  pointer-events: auto;
}
.gd-picker-card {
  background: var(--gd-panel);
  color: var(--gd-text);
  padding: 18px;
  border-radius: 12px;
  width: 350px;
  max-width: 100%;
  box-shadow: 0 8px 30px #00000033;
}
.gd-picker-card h3 {
  margin: 0 0 4px;
  font-size: 18px;
  font-weight: 500;
}
.gd-picker-card p {
  margin: 0 0 12px;
  color: var(--gd-muted);
  font-size: 12px;
}
.gd-picker-row {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 10px 0;
  border-bottom: 1px solid var(--gd-edge);
  font-size: 12px;
}
.gd-picker-row input {
  accent-color: var(--gd-accent);
}
.gd-picker-row small {
  display: block;
  font-size: 11px;
  color: var(--gd-muted);
}
.gd-picker-row > span:last-child {
  min-width: 0;
  overflow-wrap: anywhere;
}
.gd-picker-actions {
  display: flex;
  gap: 8px;
  margin-top: 14px;
}
@container gomoku (min-width:680px) {
  .gd-arena {
    grid-template-columns: minmax(0, 1fr) 236px;
    grid-template-areas: "board players";
    gap: 20px;
  }
  .gd-players {
    grid-template-columns: minmax(0, 1fr);
  }
  .gd-board-area {
    max-width: min(600px, max(240px, calc(100dvh - 136px)));
  }
}
@container gomoku (max-width:419px) {
  .gd-content {
    padding: 10px;
  }
  .gd-players {
    grid-template-columns: minmax(0, 1fr);
  }
  .gd-board-area {
    max-width: min(600px, max(240px, calc(100dvh - 612px)));
  }
  .gd-game-actions {
    gap: 6px;
  }
}
@media (pointer: coarse) {
  .gd-button {
    min-height: 44px;
  }
  .gd-danmaku-toggle {
    width: 44px;
  }
  .gd-comment-compose input {
    font-size: 16px;
  }
  .gd-picker-row {
    min-height: 44px;
  }
}
@media (prefers-reduced-motion: no-preference) {
  .gd-speech.is-new {
    animation: gd-speech-arrive 0.22s ease-out both;
  }
  @keyframes gd-speech-arrive {
    from {
      opacity: 0.3;
      transform: translateY(4px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}
body {
  margin: 0;
  color-scheme: light dark;
  background: light-dark(#f2f0e9, #181c1b);
}
button {
  cursor: pointer;
}
.gd-content {
  position: relative;
}
.gd-product button,
.gd-picker-card button {
  font-size: 12px;
}
.gd-player .gd-avatar {
  width: 40px;
  height: 40px;
}
.gd-board-footer p {
  margin: 0;
  color: var(--gd-muted);
  font-size: 11px;
}
.gd-alert {
  position: absolute;
  z-index: 5;
  top: 74px;
  left: 16px;
  right: 16px;
  padding: 12px;
  background: var(--gd-panel);
  color: var(--gd-text);
  border: 1px solid var(--gd-edge);
  border-radius: 10px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  box-shadow: 0 6px 18px #0003;
}
.gd-alert span {
  flex: 1 1 200px;
  overflow-wrap: anywhere;
  font-size: 12px;
}
.gd-picker-card {
  border: 1px solid var(--gd-edge);
  font:
    14px/1.5 system-ui,
    sans-serif;
}
.gd-picker-card::backdrop {
  background: #0b130ba8;
}
.gd-picker-options {
  max-height: 360px;
  overflow-y: auto;
}
.gd-picker-card button,
.gd-picker-card input {
  font: inherit;
}
.gd-picker-row {
  cursor: pointer;
}
.gd-picker-row input {
  width: 16px;
  height: 16px;
  flex: none;
}
.gd-picker-row > span:last-child {
  flex: 1;
}
@media (prefers-reduced-motion: no-preference) {
  .gd-speech {
    transition: background-color 0.2s;
  }
}
